SourceCode.Declaration:
/// <summary>
/// Extends class SysOperationServiceBase
/// </summary>
class AVALedgerAllocBasisRuleExportService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// process method
/// </summary>
/// <param name = "_contract">AVACRLUpdateRiscDebtorContract</param>
public void process(AVALedgerAllocBasisRuleExportContract _contract)
{
    AVAArchiveId    archiveId = _contract.parmArchiveId();
    AVAArchiveDate  archiveDate = _contract.parmArchiveDate();  
    AVALedgerAllocBasisRuleExport   archiveTable;
    LedgerAllocationRule  ledgerAllocationRule, lAllocationRule;
    LedgerAllocationRuleSource  source;
    LedgerAllocationRuleDestination destination;
    DimensionAttributeValueSetItem dimAttrValueSetItem;
    MenuFunction menuFunction;
    Args args;
    boolean createData = false;
    RecordInsertList insertList = new RecordInsertList(tableNum(AVALedgerAllocBasisRuleExport));

    select firstonly archiveTable where archiveTable.AVAArchiveId == archiveId;
    if (archiveTable)
    {
        if (Box::yesNo(strFmt("@NDX:NXAArchiveExists", archiveId), DialogButton::No) == DialogButton::Yes)
        {
            createData = true;
            delete_from archiveTable where archiveTable.AVAArchiveId == archiveId;
        }
    }
    else
    {
        createData = true;
    }

    if (createData)
    {
        while select ledgerAllocationRule
        {
            while select lAllocationRule where lAllocationRule.RuleId == ledgerAllocationRule.RuleId
                join source where source.RuleID == lAllocationRule.RuleId
            {
                archiveTable.clear();
                archiveTable.AVAArchiveId = archiveId;
                archiveTable.AVAArchiveDate = archiveDate;
                archiveTable.AVACostAllocationJournal = ledgerAllocationRule.AVACostAllocationJournal;
                archiveTable.AllocationActive = ledgerAllocationRule.AllocationActive;
                archiveTable.AllocationDescription = ledgerAllocationRule.AllocationDescription;
                archiveTable.AllocationMethod = ledgerAllocationRule.AllocationMethod;
                archiveTable.CalculationAmount = ledgerAllocationRule.CalculationAmount;
                archiveTable.CalculationType = ledgerAllocationRule.CalculationType;
                archiveTable.DataSource = ledgerAllocationRule.DataSource;
                archiveTable.DateInterval = ledgerAllocationRule.DateInterval;
                archiveTable.DateLastRun = ledgerAllocationRule.DateLastRun;
                archiveTable.DestinationAccountFrom = ledgerAllocationRule.DestinationAccountFrom;
                archiveTable.DestinationDimensionFrom = ledgerAllocationRule.DestinationDimensionFrom;
                archiveTable.EffectiveEndDate = ledgerAllocationRule.EffectiveEndDate;
                archiveTable.EffectiveStartDate = ledgerAllocationRule.EffectiveStartDate;
                archiveTable.FixedValue = ledgerAllocationRule.FixedValue;
                archiveTable.IntercompanyRule = ledgerAllocationRule.IntercompanyRule;
                archiveTable.OffsetAccountFrom = ledgerAllocationRule.OffsetAccountFrom;
                archiveTable.OffsetDefaultDimension = ledgerAllocationRule.OffsetDefaultDimension;
                archiveTable.OffsetDimensionFrom = ledgerAllocationRule.OffsetDimensionFrom;
                archiveTable.OffsetLedgerDimension = ledgerAllocationRule.OffsetLedgerDimension;
                archiveTable.RuleId = ledgerAllocationRule.RuleId;
                archiveTable.AVASequence = ledgerAllocationRule.AVASequence;
                archiveTable.SourceFieldSetting = source.FieldSetting;
                archiveTable.SourceFieldSettingStr = enum2Str(source.FieldSetting);
                archiveTable.SourceCriteria = source.SourceCriteria;
                archiveTable.SourceDimensionAttribute = source.SourceDimensionAttribute;
                archiveTable.SourceAttributeName = DimensionAttribute::find(source.SourceDimensionAttribute).Name;

                insertList.add(archiveTable);
            }

            while select lAllocationRule where lAllocationRule.RuleId == ledgerAllocationRule.RuleId
                join destination where destination.RuleID == lAllocationRule.RuleId
                join dimAttrValueSetItem where dimAttrValueSetItem.DimensionAttributeValueSet == destination.ToDefaultDimension                       
            {
                archiveTable.clear();
                archiveTable.AVAArchiveId = archiveId;
                archiveTable.AVAArchiveDate = archiveDate;
                archiveTable.AVACostAllocationJournal = ledgerAllocationRule.AVACostAllocationJournal;
                archiveTable.AllocationActive = ledgerAllocationRule.AllocationActive;
                archiveTable.AllocationDescription = ledgerAllocationRule.AllocationDescription;
                archiveTable.AllocationMethod = ledgerAllocationRule.AllocationMethod;
                archiveTable.CalculationAmount = ledgerAllocationRule.CalculationAmount;
                archiveTable.CalculationType = ledgerAllocationRule.CalculationType;
                archiveTable.DataSource = ledgerAllocationRule.DataSource;
                archiveTable.DateInterval = ledgerAllocationRule.DateInterval;
                archiveTable.DateLastRun = ledgerAllocationRule.DateLastRun;
                archiveTable.DestinationAccountFrom = ledgerAllocationRule.DestinationAccountFrom;
                archiveTable.DestinationDimensionFrom = ledgerAllocationRule.DestinationDimensionFrom;
                archiveTable.EffectiveEndDate = ledgerAllocationRule.EffectiveEndDate;
                archiveTable.EffectiveStartDate = ledgerAllocationRule.EffectiveStartDate;
                archiveTable.FixedValue = ledgerAllocationRule.FixedValue;
                archiveTable.IntercompanyRule = ledgerAllocationRule.IntercompanyRule;
                archiveTable.OffsetAccountFrom = ledgerAllocationRule.OffsetAccountFrom;
                archiveTable.OffsetDefaultDimension = ledgerAllocationRule.OffsetDefaultDimension;
                archiveTable.OffsetDimensionFrom = ledgerAllocationRule.OffsetDimensionFrom;
                archiveTable.OffsetLedgerDimension = ledgerAllocationRule.OffsetLedgerDimension;
                archiveTable.RuleId = ledgerAllocationRule.RuleId;
                archiveTable.AVASequence = ledgerAllocationRule.AVASequence;
                archiveTable.DestBasisId = destination.BasisId;
                archiveTable.DestFixedPercent = destination.FixedPercent;
                archiveTable.DestFixedWeight = destination.FixedWeight;
                archiveTable.DestToCompany = destination.ToCompany;
                archiveTable.DestToDefaultDimension = destination.ToDefaultDimension;
                archiveTable.DestToLedgerDimension = destination.ToLedgerDimension;
                archiveTable.DestToDimValue = dimAttrValueSetItem.DisplayValue;
                archiveTable.DestToDimAttribute = DimensionAttribute::find(DimensionAttributeValue::find(dimAttrValueSetItem.DimensionAttributeValue).DimensionAttribute).Name;
                archiveTable.DestToLedgerMainAcc = LedgerDimensionFacade::getMainAccountIdFromLedgerDimension(destination.ToLedgerDimension);
                archiveTable.AVARuleSourceAccountNum = destination.AVARuleSourceAccountNum;

                insertList.add(archiveTable);
            }
        }
        insertList.insertDatabase();
    }

    args = new Args(this);
    args.parm(archiveId);
    menuFunction = new MenuFunction(menuItemDisplayStr(AVALedgerAllocBasisRuleExportFrm), MenuItemType::Display);
    menuFunction.run(args);

}
